  const [sort,setSort]=useState('relevance'); const params=useMemo(()=>({q:q||undefined,category:category||undefined,deliveryMode:mode||undefined,city:city||undefined,sort:sort as any,page:1,pageSize:12}),[q,category,mode,city,sort]);
